import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {10, 9, 2, 5, 3, 7, 101, 18};
        // tails[k] = smallest ending value of an increasing run of length k+1
        int[] tails = new int[nums.length];
        int size = 0;
        for (int x : nums) {
            // binary search: first position whose tail is >= x
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails[mid] < x) lo = mid + 1; else hi = mid;
            }
            tails[lo] = x;            // replace: same length, smaller ending
            if (lo == size) size++;   // nothing was >= x, so x made a longer run
        }
        System.out.println("nums: " + Arrays.toString(nums));
        System.out.println("tails: " + Arrays.toString(Arrays.copyOf(tails, size)));
        System.out.println("LIS length: " + size);
    }
    // Time O(N log N), extra space O(N).
}

