    vector<int> tails;
    for (int x : nums) {
        // binary search: first position whose tail is >= x
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);  // x made a longer run
        else *it = x;                               // same length, smaller ending
    }
    cout << "nums: " << show(nums) << "\n";
    cout << "tails: " << show(tails) << "\n";
    cout << "LIS length: " << tails.size() << "\n";
    return 0;
}
