import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] env = {{5, 4}, {6, 4}, {6, 7}, {2, 3}};
        System.out.println("envelopes (w,h): " + Arrays.deepToString(env));
        // width ascending; equal widths by height DESCENDING so they cannot chain
        Arrays.sort(env, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
        int[] heights = new int[env.length];
        for (int i = 0; i < env.length; i++) heights[i] = env[i][1];
        System.out.println("heights after sort: " + Arrays.toString(heights));
        // strict LIS on heights with the tails array
        int[] tails = new int[heights.length];
        int size = 0;
        for (int h : heights) {
            int lo = 0, hi = size;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails[mid] < h) lo = mid + 1; else hi = mid;
            }
            tails[lo] = h;
            if (lo == size) size++;
        }
        System.out.println("max nested: " + size);
    }
    // Time O(N log N), extra space O(N).
}

