using namespace std;

int main() {
    vector<pair<int,int>> env = {{5, 4}, {6, 4}, {6, 7}, {2, 3}};
    cout << "envelopes (w,h): [";
    for (size_t i = 0; i < env.size(); i++)
        cout << (i ? ", " : "") << "[" << env[i].first << ", " << env[i].second << "]";
    cout << "]\n";
    // width ascending; equal widths by height DESCENDING so they cannot chain
    sort(env.begin(), env.end(), [](const pair<int,int>& a, const pair<int,int>& b) {
        return a.first != b.first ? a.first < b.first : a.second > b.second;
    });
    cout << "heights after sort: [";
    for (size_t i = 0; i < env.size(); i++) cout << (i ? ", " : "") << env[i].second;
    cout << "]\n";
    // strict LIS on heights with the tails array
    vector<int> tails;
    for (auto& e : env) {
        auto it = lower_bound(tails.begin(), tails.end(), e.second);
        if (it == tails.end()) tails.push_back(e.second); else *it = e.second;
    }
    cout << "max nested: " << tails.size() << "\n";
    return 0;
}
// Time O(N log N), extra space O(N).

