import java.util.*;

public class Main {
    static boolean canBreak(String s, String[] words) {
        Set<String> dict = new HashSet<>(Arrays.asList(words));
        int maxLen = 0;
        for (String w : words) maxLen = Math.max(maxLen, w.length());
        int n = s.length();
        boolean[] dp = new boolean[n + 1];   // dp[i]: can s[0..i) be split?
        dp[0] = true;                        // the empty prefix needs no words
        for (int i = 1; i <= n; i++) {
            // the last word is s[j..i); it cannot be longer than maxLen
            for (int j = Math.max(0, i - maxLen); j < i && !dp[i]; j++) {
                if (dp[j] && dict.contains(s.substring(j, i))) dp[i] = true;
            }
        }
        return dp[n];
    }

    static void show(String s, String[] words) {
        System.out.println("s=" + s + " words=[" + String.join(", ", words) + "] -> "
            + (canBreak(s, words) ? "yes" : "no"));
    }

    public static void main(String[] args) {
        show("applepenapple", new String[]{"apple", "pen"});
        show("catsandog", new String[]{"cats", "dog", "sand", "and", "cat"});
    }
    // Time O(N * maxLen^2) (each lookup hashes up to maxLen chars), space O(N).
}

