using namespace std;

bool canBreak(const string& s, const vector<string>& words) {
    unordered_set<string> dict(words.begin(), words.end());
    int maxLen = 0;
    for (auto& w : words) maxLen = max(maxLen, (int)w.size());
    int n = s.size();
    vector<bool> dp(n + 1, false);   // dp[i]: can s[0..i) be split?
    dp[0] = true;                    // the empty prefix needs no words
    for (int i = 1; i <= n; i++) {
        // the last word is s[j..i); it cannot be longer than maxLen
        for (int j = max(0, i - maxLen); j < i && !dp[i]; j++) {
            if (dp[j] && dict.count(s.substr(j, i - j))) dp[i] = true;
        }
    }
    return dp[n];
}

void show(const string& s, const vector<string>& words) {
    cout << "s=" << s << " words=[";
    for (size_t i = 0; i < words.size(); i++) cout << (i ? ", " : "") << words[i];
    cout << "] -> " << (canBreak(s, words) ? "yes" : "no") << "\n";
}

