public class Main {
    static int minCut(String s) {
        int n = s.length();
        // cuts[i] = fewest cuts for the first i characters; cuts[0] = -1 so that
        // "whole prefix is a palindrome" gives -1 + 1 = 0 cuts
        int[] cuts = new int[n + 1];
        for (int i = 0; i <= n; i++) cuts[i] = i - 1;   // worst case: cut everywhere
        // 2n-1 centres: each letter (odd length) and each gap (even length)
        for (int c = 0; c < 2 * n - 1; c++) {
            int l = c / 2, r = l + c % 2;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                // s[l..r] is a palindrome: use it as the last piece
                cuts[r + 1] = Math.min(cuts[r + 1], cuts[l] + 1);
                l--; r++;
            }
        }
        return cuts[n];
    }

    public static void main(String[] args) {
        for (String s : new String[]{"aab", "abccbx", "racecar"}) {
            System.out.println(s + " -> min cuts: " + minCut(s));
        }
    }
    // Time O(N^2), extra space O(N).
}

