import java.util.*;

public class Main {
    public static void main(String[] args) {
        // matrix i has size dims[i-1] x dims[i], so there are 4 matrices here
        int[] dims = {40, 20, 30, 10, 30};
        int n = dims.length - 1;
        // dp[i][j] = fewest multiplications to compute matrices i..j (1-based)
        int[][] dp = new int[n + 1][n + 1];
        for (int len = 2; len <= n; len++) {            // short ranges first
            for (int i = 1; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {           // last multiplication: (i..k) x (k+1..j)
                    int cost = dp[i][k] + dp[k + 1][j] + dims[i - 1] * dims[k] * dims[j];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        System.out.println("dims: " + Arrays.toString(dims));
        System.out.println("min multiplications: " + dp[1][n]);
    }
    // Time O(N^3), space O(N^2).
}

