import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {3, 1, 5, 8};
        int n = nums.length;
        // pad with 1 on both ends so every balloon has two neighbours
        int[] b = new int[n + 2];
        b[0] = 1; b[n + 1] = 1;
        for (int i = 0; i < n; i++) b[i + 1] = nums[i];
        // dp[i][j] = max coins from bursting only balloons i..j (walls i-1 and j+1 alive)
        int[][] dp = new int[n + 2][n + 2];
        for (int len = 1; len <= n; len++) {
            for (int i = 1; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                for (int k = i; k <= j; k++) {   // k is burst last, between the two walls
                    int coins = dp[i][k - 1] + b[i - 1] * b[k] * b[j + 1] + dp[k + 1][j];
                    dp[i][j] = Math.max(dp[i][j], coins);
                }
            }
        }
        System.out.println("balloons: " + Arrays.toString(nums));
        System.out.println("max coins: " + dp[1][n]);
    }
    // Time O(N^3), space O(N^2).
