import java.util.*;

public class Main {
    // The tree is stored in arrays: node i has value val[i] and children
    // left[i], right[i] (-1 means no child). Node 0 is the root.
    static int[] val = {3, 2, 3, 3, 1};
    static int[] left = {1, -1, -1, -1, -1};
    static int[] right = {2, 3, 4, -1, -1};

    // returns {best if this node is robbed, best if it is skipped}
    static int[] dfs(int node) {
        if (node == -1) return new int[]{0, 0};
        int[] l = dfs(left[node]), r = dfs(right[node]);   // children first (post-order)
        int rob = val[node] + l[1] + r[1];                 // children must be skipped
        int skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]);  // children are free
        return new int[]{rob, skip};
    }

    public static void main(String[] args) {
        System.out.println("val:   " + Arrays.toString(val));
        System.out.println("left:  " + Arrays.toString(left));
        System.out.println("right: " + Arrays.toString(right));
        int[] res = dfs(0);
        System.out.println("rob root: " + res[0] + ", skip root: " + res[1]);
        System.out.println("max loot: " + Math.max(res[0], res[1]));
    }
    // Time O(N): every node is visited once. Space O(H) for the call stack.
}

