import java.util.*;

public class Main {
    static int[] val, left, right;   // tree in arrays; -1 means no child; node 0 is the root
    static int best;

    // returns the best STRAIGHT path that starts at node and goes down one side
    static int gain(int node) {
        if (node == -1) return 0;
        int l = Math.max(0, gain(left[node]));    // clip: drop a branch that loses money
        int r = Math.max(0, gain(right[node]));
        best = Math.max(best, val[node] + l + r); // path that bends at this node
        return val[node] + Math.max(l, r);        // the parent may use only one side
    }

    static void solve(int[] v, int[] l, int[] r) {
        val = v; left = l; right = r;
        best = Integer.MIN_VALUE;                 // not 0: all values may be negative
        gain(0);
        System.out.println("val: " + Arrays.toString(v) + " -> max path sum: " + best);
    }

    public static void main(String[] args) {
        solve(new int[]{-10, 9, 20, 15, 7}, new int[]{1, -1, 3, -1, -1}, new int[]{2, -1, 4, -1, -1});
        solve(new int[]{-3, -2, -5}, new int[]{1, -1, -1}, new int[]{2, -1, -1});
    }
    // Time O(N), space O(H) for the call stack.
}

