import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] prices = {1, 3, 2, 8, 4, 9};
        int fee = 2;
        int NEG = -1000000000;          // stands for "impossible"
        int hold = NEG, sold = NEG, rest = 0;
        for (int p : prices) {
            // compute today's values from YESTERDAY's values only
            int newHold = Math.max(hold, rest - p);  // keep the share, or buy from rest
            int newSold = hold + p - fee;            // sell today, pay the fee once
            int newRest = Math.max(rest, sold);      // stay free, or finish the cooldown
            hold = newHold; sold = newSold; rest = newRest;
        }
        System.out.println("prices: " + Arrays.toString(prices) + ", fee: " + fee);
        System.out.println("max profit: " + Math.max(sold, rest));
    }
    // Time O(N), extra space O(1).
}

