import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] prices = {3, 2, 6, 5, 0, 3};
        int k = 4;
        // buy[j]  = best cash while holding a share in the j-th trade
        // sell[j] = best cash after finishing at most j trades
        int[] buy = new int[k + 1], sell = new int[k + 1];
        Arrays.fill(buy, -1000000000);
        for (int p : prices) {
            for (int j = 1; j <= k; j++) {
                buy[j] = Math.max(buy[j], sell[j - 1] - p);  // start trade j today
                sell[j] = Math.max(sell[j], buy[j] + p);     // finish trade j today
            }
        }
        // buying and selling on the same day costs 0, so spare trades are free
        System.out.println("prices: " + Arrays.toString(prices));
        System.out.println("sell[0..k]: " + Arrays.toString(sell));
        System.out.println("answer for k=" + k + ": " + sell[k]);
    }
    // Time O(N * k), extra space O(k).
}

