code.java:
public class Main {
    public static void main(String[] args) {
        String s = "rabbbit", t = "rabbit";
        int n = s.length(), m = t.length();
        int[][] lcs = new int[n + 1][m + 1], ed = new int[n + 1][m + 1], ds = new int[n + 1][m + 1];
        // base borders: edit distance = delete/insert everything; one way to make ""
        for (int i = 0; i <= n; i++) { ed[i][0] = i; ds[i][0] = 1; }
        for (int j = 0; j <= m; j++) ed[0][j] = j;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                boolean same = s.charAt(i - 1) == t.charAt(j - 1);
                // LCS: match -> diagonal + 1, else best of up / left
                lcs[i][j] = same ? lcs[i - 1][j - 1] + 1 : Math.max(lcs[i - 1][j], lcs[i][j - 1]);
                // Edit: match -> diagonal, else 1 + min(replace, delete, insert)
                ed[i][j] = same ? ed[i - 1][j - 1]
                    : 1 + Math.min(ed[i - 1][j - 1], Math.min(ed[i - 1][j], ed[i][j - 1]));
                // Distinct: always "skip s[i-1]" (up); on a match also "use it" (diagonal)
                ds[i][j] = ds[i - 1][j] + (same ? ds[i - 1][j - 1] : 0);
            }
        }
        System.out.println("s=" + s + " t=" + t);
        System.out.println("LCS length: " + lcs[n][m]);
        System.out.println("edit distance: " + ed[n][m]);
        System.out.println("distinct subsequences of s equal to t: " + ds[n][m]);
    }
    // Time O(n * m), space O(n * m) for each table.
}

