    ed[i][j] = same ? ed[i - 1][j - 1] : 1 + Math.min(ed[i - 1][j - 1], ed[i - 1][j], ed[i][j - 1]);
    // Distinct: always "skip s[i-1]" (up); on a match also "use it" (diagonal)
    ds[i][j] = ds[i - 1][j] + (same ? ds[i - 1][j - 1] : 0);
  }
}
