public class Main {
    // regex: '.' is any one char, "x*" is zero or more copies of x
    static boolean regex(String s, String p) {
        int n = s.length(), m = p.length();
        boolean[][] dp = new boolean[n + 1][m + 1];
        dp[0][0] = true;
        for (int j = 2; j <= m; j++) dp[0][j] = p.charAt(j - 1) == '*' && dp[0][j - 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                char c = p.charAt(j - 1);
                if (c == '*' && j >= 2) {
                    char x = p.charAt(j - 2);           // the element the star repeats
                    dp[i][j] = dp[i][j - 2]             // zero copies of x
                        || ((x == '.' || x == s.charAt(i - 1)) && dp[i - 1][j]);  // one more copy
                } else {
                    dp[i][j] = dp[i - 1][j - 1] && (c == '.' || c == s.charAt(i - 1));
                }
            }
        }
        return dp[n][m];
    }

    // wildcard: '?' is any one char, '*' alone is any sequence of chars
    static boolean wildcard(String s, String p) {
        int n = s.length(), m = p.length();
        boolean[][] dp = new boolean[n + 1][m + 1];
        dp[0][0] = true;
        for (int j = 1; j <= m; j++) dp[0][j] = p.charAt(j - 1) == '*' && dp[0][j - 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                char c = p.charAt(j - 1);
                if (c == '*') dp[i][j] = dp[i][j - 1] || dp[i - 1][j];   // empty, or eat one char
                else dp[i][j] = dp[i - 1][j - 1] && (c == '?' || c == s.charAt(i - 1));
            }
        }
        return dp[n][m];
    }

    public static void main(String[] args) {
        String[][] tests = {{"aab", "c*a*b"}, {"aaa", "a*"}, {"abc", "a*"}};
        for (String[] t : tests) {
            System.out.println("s=" + t[0] + " p=" + t[1] + " regex=" + (regex(t[0], t[1]) ? "yes" : "no")
                + " wildcard=" + (wildcard(t[0], t[1]) ? "yes" : "no"));
        }
    }
    // Time O(n * m), space O(n * m) for each matcher.
}

