def regex(s, p):
    """regex: '.' is any one char, 'x*' is zero or more copies of x"""
    n, m = len(s), len(p)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for j in range(2, m + 1):
        dp[0][j] = p[j - 1] == "*" and dp[0][j - 2]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            c = p[j - 1]
            if c == "*" and j >= 2:
                x = p[j - 2]   # the element the star repeats
                # zero copies of x, or one more copy of x
                dp[i][j] = dp[i][j - 2] or (x in (".", s[i - 1]) and dp[i - 1][j])
            else:
                dp[i][j] = dp[i - 1][j - 1] and c in (".", s[i - 1])
    return dp[n][m]


def wildcard(s, p):
    """wildcard: '?' is any one char, '*' alone is any sequence of chars"""
    n, m = len(s), len(p)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for j in range(1, m + 1):
        dp[0][j] = p[j - 1] == "*" and dp[0][j - 1]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            c = p[j - 1]
            if c == "*":
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]   # empty, or eat one char
            else:
                dp[i][j] = dp[i - 1][j - 1] and c in ("?", s[i - 1])
    return dp[n][m]


for s, p in [("aab", "c*a*b"), ("aaa", "a*"), ("abc", "a*")]:
    r = "yes" if regex(s, p) else "no"
    w = "yes" if wildcard(s, p) else "no"
    print("s=" + s + " p=" + p + " regex=" + r + " wildcard=" + w)
# Time O(n * m), space O(n * m) for each matcher.

