                char x = p[j - 2];                  // the element the star repeats
                dp[i][j] = dp[i][j - 2]             // zero copies of x
                    || ((x == '.' || x == s[i - 1]) && dp[i - 1][j]);  // one more copy
            } else {
                dp[i][j] = dp[i - 1][j - 1] && (c == '.' || c == s[i - 1]);
            }
        }
    }
    return dp[n][m];
}

// wildcard: '?' is any one char, '*' alone is any sequence of chars
bool wildcardMatch(const string& s, const string& p) {
